package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen0Test {

    @Test
    public void testTranslate_MatchFound_Greedy() throws IOException {
        // Setup: "ab" -> "1", "abc" -> "2"
        // Testing greedy: if input is "abc", it should pick "abc" (length 3) over "ab" (length 2)
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"ab", "abc"},
                new CharSequence[]{"1", "2"}
        );
        // Note: The constructor in LookupTranslator takes pairs. 
        // Since the provided signature is (CharSequence[]... lookup), 
        // we pass arrays of pairs.

        // Re-constructing based on common LookupTranslator implementation pattern:
        // The constructor takes pairs of (search, replacement)
        LookupTranslator actualTranslator = new LookupTranslator(
                new CharSequence[]{"ab", "1"},
                new CharSequence[]{"abc", "2"}
        );
        // Wait, the signature is CharSequence[]... lookup. 
        // This usually means lookup[0] is {key1, val1, key2, val2...} or lookup[0]={key1, key2}, lookup[1]={val1, val2}
        // Given the code uses lookupMap.get(subSeq), it's a map-based lookup.
        // Standard Apache Commons LookupTranslator constructor: 
        // public LookupTranslator(final CharSequence[]... lookup) 
        // where lookup[0] are keys and lookup[1] are values.

        LookupTranslator translatorCorrect = new LookupTranslator(
                new CharSequence[]{"ab", "abc"},
                new CharSequence[]{"1", "2"}
        );

        StringWriter out = new StringWriter();
        String input = "abcde";

        // Test greedy: should find "abc" (length 3)
        int length = translatorCorrect.translate(input, 0, out);

        assertEquals(3, length);
        assertEquals("2", out.toString());
    }

    @Test
    public void testTranslate_MatchFound_Shortest() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"},
                new CharSequence[]{"X"}
        );
        StringWriter out = new StringWriter();
        int length = translator.translate("abc", 0, out);

        assertEquals(1, length);
        assertEquals("X", out.toString());
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"z"},
                new CharSequence[]{"X"}
        );
        StringWriter out = new StringWriter();
        int length = translator.translate("abc", 0, out);

        assertEquals(0, length);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_IndexOutOfBounds_Boundary() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"abc"},
                new CharSequence[]{"X"}
        );
        StringWriter out = new StringWriter();

        // input length is 3. index is 1. 
        // longest is 3. index + longest = 4. 4 > 3.
        // max becomes 3 - 1 = 2.
        // Loop checks subseq of length 2 ("bc") and 1 ("b").
        // Neither match.
        int length = translator.translate("abc", 1, out);

        assertEquals(0, length);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_PartialMatchAtEnd() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"bc"},
                new CharSequence[]{"Y"}
        );
        StringWriter out = new StringWriter();

        // input "abc", index 1. subseq(1, 3) is "bc".
        int length = translator.translate("abc", 1, out);

        assertEquals(2, length);
        assertEquals("Y", out.toString());
    }

    @Test
    public void testTranslate_EmptyInput() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"},
                new CharSequence[]{"X"}
        );
        StringWriter out = new StringWriter();
        int length = translator.translate("", 0, out);

        assertEquals(0, length);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_IndexAtEnd() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"},
                new CharSequence[]{"X"}
        );
        StringWriter out = new StringWriter();
        // index = input.length()
        int length = translator.translate("abc", 3, out);

        assertEquals(0, length);
        assertEquals("", out.toString());
    }
}
